const rs = await Promise.all([
  tools.exec_command({cmd:"entire trail show --branch fix/scip-followups","workdir":"/Users/thomi/Projects/entire-graph","yield_time_ms":30000,"max_output_tokens":20000}),
  tools.exec_command({cmd:"entire agent-help trail watch","workdir":"/Users/thomi/Projects/entire-graph","yield_time_ms":10000,"max_output_tokens":12000}),
  tools.exec_command({cmd:"entire agent-help trail finding","workdir":"/Users/thomi/Projects/entire-graph","yield_time_ms":10000,"max_output_tokens":12000}),
  tools.exec_command({cmd:"entire agent-help search","workdir":"/Users/thomi/Projects/entire-graph","yield_time_ms":10000,"max_output_tokens":12000})
]);
rs.forEach((r,i)=>text(`---RESULT ${i+1}---\n${r.output}`));

const branches = [
"fix/cross-language-name-only-edges",
"audit/lang-cpp-inclass-declarations",
"audit/lang-c-data-members",
"audit/lang-cpp-declarator-names",
"audit/seam-repo-key-handshake",
"audit/graph-fsharp-pipeline-calls",
"audit/graph-julia-module-calls",
"audit/graph-cache-write-confinement",
"fix/scip-followups",
"rfd/reference-positions",
"fix/committed-tree-regular-files",
"rfd/converge-code-search",
"security/mark-payload-record-provenance",
"security/enforce-wall-clock-budget",
"security/surface-ignored-exclusions"
];
const rs = await Promise.all(branches.map(branch => tools.exec_command({
  cmd:`entire trail finding --trail ${JSON.stringify(branch)} --status open --freshness current --limit 100 --json`,
  workdir:"/Users/thomi/Projects/entire-graph",
  yield_time_ms:30000,
  max_output_tokens:20000
})));
for (let i=0;i<rs.length;i++) {
  let obj;
  try { obj = JSON.parse(rs[i].output); } catch { text(`${branches[i]} PARSE_ERROR\n${rs[i].output}`); continue; }
  const reduced = {
    branch: branches[i],
    counts: obj.counts,
    current_open: (obj.findings||[]).map(f=>({
      severity:f.severity,
      confidence:f.confidence,
      body:f.body,
      file:f.location?.filePath,
      line:f.location?.startLine
    }))
  };
  text(JSON.stringify(reduced));
}

const specs = [
  ["160","origin/audit/graph-cache-write-confinement"],
  ["169","origin/audit/seam-repo-key-handshake"],
  ["153","origin/fix/scip-followups"]
];
const rs = await Promise.all(specs.map(([n,ref])=>tools.exec_command({
  cmd:`entire graph diff --repo . --base main --head ${ref} --json`,
  workdir:"/Users/thomi/Projects/entire-graph",
  yield_time_ms:30000,
  max_output_tokens:18000
})));
rs.forEach((r,i)=>text(`PR #${specs[i][0]}\n${r.output}`));

const nums=[160,169,153];
const rs=await Promise.all(nums.map(n=>tools.exec_command({
  cmd:`gh pr view ${n} --json number,title,url,body,baseRefName,headRefName,mergeable,mergeStateStatus,isDraft,reviewDecision,commits,files,comments,reviews`,
  workdir:"/Users/thomi/Projects/entire-graph",
  yield_time_ms:30000,
  max_output_tokens:25000
})));
for(let i=0;i<rs.length;i++) {
  let o; try{o=JSON.parse(rs[i].output);}catch{text(`PR ${nums[i]}\n${rs[i].output}`);continue;}
  const reduced={
    number:o.number,title:o.title,url:o.url,base:o.baseRefName,head:o.headRefName,
    mergeable:o.mergeable,mergeStateStatus:o.mergeStateStatus,isDraft:o.isDraft,
    reviewDecision:o.reviewDecision,body:o.body,
    commits:(o.commits||[]).map(c=>({oid:c.oid.slice(0,8),messageHeadline:c.messageHeadline,authoredDate:c.authoredDate})),
    files:(o.files||[]).map(f=>({path:f.path,additions:f.additions,deletions:f.deletions})),
    comments:(o.comments||[]).map(c=>({author:c.author?.login,createdAt:c.createdAt,body:c.body})),
    reviews:(o.reviews||[]).map(r=>({author:r.author?.login,state:r.state,submittedAt:r.submittedAt,body:r.body}))
  };
  text(JSON.stringify(reduced,null,2));
}

