+	t.Parallel()
+	sentinel := errors.New("randomness source unavailable")
+	if _, err := cacheTempNameSuffix(iotest.ErrReader(sentinel)); !errors.Is(err, sentinel) {
+		t.Fatalf("cacheTempNameSuffix error = %v, want it to report %v", err, sentinel)
+	}
