+	if _, err := cacheTempNameSuffix(strings.NewReader("too short")); !errors.Is(err, io.ErrUnexpectedEOF) {
+		t.Fatalf("cacheTempNameSuffix error = %v, want %v", err, io.ErrUnexpectedEOF)
+	}
