 	snapshot := ProviderSnapshot{Header: SnapshotHeader{
 		RepoKey:         "github.com/example/repo",
 		Commit:          "old-commit",
 		Tree:            "tree",
 		Provider:        ProviderName,
 		ProviderVersion: "test-version",
 		Profile:         string(ProfileFull),
 	}}
